-- Private installation candidate. No connection is opened by generating this file.
-- Use psql --no-psqlrc --file=scripts/install-schooling-read-v6-transaction.sql
-- only in an explicitly authorized owner session, after verifying release hashes.
-- Any failure stops psql before COMMIT; disconnect rolls the transaction back.
\set ON_ERROR_STOP on
BEGIN;
\ir migrations/191-schooling-set-based-read.sql
DO $read_v6_install_admission$
DECLARE admission jsonb;
BEGIN
 EXECUTE $preflight$WITH expected AS MATERIALIZED (
 SELECT value AS pin FROM jsonb_array_elements($1::jsonb)
), owner_anchor AS MATERIALIZED (
 SELECT p.proowner FROM pg_proc p
 WHERE p.oid=to_regprocedure('public.school_certificate_read_v5(text,uuid,integer,text,uuid,uuid,uuid)')
  AND encode(pg_catalog.sha256(convert_to(replace(p.prosrc,E'\r\n',E'\n'),'UTF8')),'hex')='6acaf9ff8b684060602725e8832c349d23c15594366c12daec723436e4930869'
), checked AS (
 SELECT count(*)::integer AS checked_count,bool_and(coalesce(
  p.oid IS NOT NULL AND p.proowner=a.proowner AND p.prokind='f' AND p.provariadic=0 AND NOT p.proisstrict AND NOT p.proleakproof AND p.proparallel='u'
  AND p.prosecdef IS NOT DISTINCT FROM (e.pin->>'securityDefiner')::boolean AND p.proretset IS NOT DISTINCT FROM (e.pin->>'returnsSet')::boolean
  AND p.provolatile::text=e.pin->>'volatility' AND l.lanname=e.pin->>'language' AND p.prorettype=(e.pin->>'returnType')::regtype
  AND EXISTS(SELECT 1 FROM jsonb_array_elements(e.pin->'searchPaths') config WHERE config=to_jsonb(p.proconfig))
  AND coalesce(p.proargnames,ARRAY[]::text[])=ARRAY(SELECT jsonb_array_elements_text(e.pin->'argNames'))
  AND ARRAY(SELECT unnest(coalesce(p.proallargtypes,p.proargtypes::oid[])))=ARRAY(SELECT value::regtype::oid FROM jsonb_array_elements_text(e.pin->'argTypes') t(value))
  AND coalesce(p.proargmodes,array_fill('i'::"char",ARRAY[p.pronargs]))::text[]=ARRAY(SELECT jsonb_array_elements_text(e.pin->'argModes'))
  AND pg_get_expr(p.proargdefaults,0) IS NOT DISTINCT FROM e.pin->>'defaults'
  AND encode(pg_catalog.sha256(convert_to(replace(p.prosrc,E'\r\n',E'\n'),'UTF8')),'hex')=e.pin->>'sha256'
  AND has_function_privilege('municontrol_actions_runtime_app',p.oid,'EXECUTE') IS NOT DISTINCT FROM (e.pin->>'runtimeAllowed')::boolean
  AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) acl WHERE acl.grantee<>p.proowner
   AND NOT((e.pin->>'runtimeAllowed')::boolean AND acl.grantee=(SELECT oid FROM pg_roles WHERE rolname='municontrol_actions_runtime_app') AND acl.privilege_type='EXECUTE' AND NOT acl.is_grantable))
 ,false)) AS accepted
 FROM expected e CROSS JOIN owner_anchor a
 LEFT JOIN pg_proc p ON p.oid=to_regprocedure(e.pin->>'signature')
 LEFT JOIN pg_language l ON l.oid=p.prolang
)
SELECT jsonb_build_object('version','schooling-read-v6-admission.v1','implementation','v6','payloadVersion','family-schooling.v5',
 'ready',coalesce(c.checked_count=15 AND c.accepted
  AND EXISTS(SELECT 1 FROM pg_roles WHERE rolname='municontrol_actions_runtime_app' AND NOT rolsuper AND NOT rolbypassrls)
  AND (SELECT count(*) FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname=ANY(ARRAY['school_certificate_read_source_v6','school_certificate_read_v6']))=2
  AND has_function_privilege(current_user,to_regprocedure('public.school_certificate_read_v6(text,uuid,integer,text,uuid,uuid,uuid)'),'EXECUTE'),false)) AS result
